/* ============================================================
   PATCH 1.0.13 — Автообновление в меню пользователя
   ============================================================ */
(function(){
'use strict';
if (window.__trkAutoUpdateMenuV113) return;
window.__trkAutoUpdateMenuV113 = true;

var _cbMenu = document.getElementById('udAutoUpdate');
var _wrap = document.getElementById('udAutoUpdateWrap');

// Если пункта нет (нет прав или не отрендерился) — выходим
if (!_cbMenu) return;

function _syncCheckboxes(val) {
    _cbMenu.checked = val;
    var _cbModal = document.getElementById('trkUpdateAuto');
    if (_cbModal) _cbModal.checked = val;
}

function _saveSetting(val) {
    _syncCheckboxes(val);
    var csrf = window.REESTR_CSRF || '';
    var hdrs = {'Content-Type': 'application/json'};
    if (csrf) hdrs['X-CSRF-Token'] = csrf;

    fetch('/api/plugins/updater/settings', {
        method: 'POST', credentials: 'same-origin', headers: hdrs,
        body: JSON.stringify({auto_update: val})
    }).catch(function(){});
}

// 1. Загружаем текущее состояние при старте
fetch('/api/plugins/updater/settings', {credentials: 'same-origin'})
    .then(function(r) { return r.json(); })
    .then(function(d) {
        if (d && d.success) _syncCheckboxes(d.auto_update);
    })
    .catch(function(){});

// 2. Обработчик клика по чекбоксу в меню
_cbMenu.addEventListener('change', function(e) {
    e.stopPropagation();
    _saveSetting(this.checked);
});

// 3. Чтобы меню не закрывалось при клике на чекбокс или его label
_cbMenu.addEventListener('click', function(e) { e.stopPropagation(); });
if (_wrap) {
    _wrap.addEventListener('click', function(e) {
        // Если кликнули не по самому чекбоксу, а по тексту/иконке — переключаем вручную
        if (e.target !== _cbMenu) {
            e.preventDefault();
            e.stopPropagation();
            _cbMenu.checked = !_cbMenu.checked;
            _saveSetting(_cbMenu.checked);
        }
    });
}

// 4. Синхронизация из модалки (если пользователь поменял настройку там)
var _origShowModal = window.__trkUpdateNotifierV3 ? true : false;
document.addEventListener('change', function(e) {
    if (e.target && e.target.id === 'trkUpdateAuto') {
        _syncCheckboxes(e.target.checked);
    }
});

})();
